package config

import (
	"archive/tar"
	"fmt"
)

type Config struct {
	Host string
	Port int
}

func (c *Config) Addr() string {
	return fmt.Sprintf("%s:%d", c.Host, c.Port)
}

arguments.CommandLine:
"go run -e /dev/stdin << 'EOF'
package main

import (
	"fmt"
	"golang.org/x/tools/go/packages"
)

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles,
		Tests: true,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	for _, p := range pkgs {
		fmt.Printf("ID: %s, Name: %s, Files: %v, Errors: %v\n", p.ID, p.Name, p.GoFiles, p.Errors)
	}
}
EOF"

